__global__ void block_sum(const float* in, float* out, int n)
{
    extern __shared__ float sdata[];

    unsigned int tid = threadIdx.x;
    unsigned int idx = blockIdx.x * blockDim.x + threadIdx.x;

    // Load with bounds check; out-of-range threads contribute 0.0f.
    sdata[tid] = (idx < (unsigned int)n) ? in[idx] : 0.0f;

    __syncthreads();

    // Tree reduction: every thread in the block participates,
    // so every thread reaches every __syncthreads().
    for (unsigned int stride = blockDim.x / 2; stride > 0; stride >>= 1) {
        if (tid < stride) {
            sdata[tid] += sdata[tid + stride];
        }
        __syncthreads();
    }

    if (tid == 0) {
        out[blockIdx.x] = sdata[0];
    }
}
